namespace ghidra.file.formats.zstd;

using static ghidra.formats.gfilesystem.fileinfo.FileAttributeType;





using ghidra.app.util.bin;
using ghidra.file.cliwrapper;
using ghidra.file.cliwrapper.ArchiverCliToolWrapper;
using ghidra.file.formats.sevenzip;
